import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        long[][] a = new long[n][];
        for (int i = 0; i < n; i++) a[i] = new long[] {next(), next()};
        Arrays.sort(a, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        List<long[]> out = new ArrayList<>();
        for (long[] iv : a) {
            // Sharing an endpoint counts as overlapping.
            if (!out.isEmpty() && iv[0] <= out.get(out.size() - 1)[1]) {
                long[] last = out.get(out.size() - 1);
                last[1] = Math.max(last[1], iv[1]);
            } else out.add(new long[] {iv[0], iv[1]});
        }
        StringBuilder sb = new StringBuilder().append(out.size()).append('\n');
        for (long[] iv : out) sb.append(iv[0]).append(' ').append(iv[1]).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"cmp"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	a := make([][2]int64, n)
	for i := range a {
		a[i] = [2]int64{next(), next()}
	}
	slices.SortFunc(a, func(x, y [2]int64) int {
		if x[0] != y[0] {
			return cmp.Compare(x[0], y[0])
		}
		return cmp.Compare(x[1], y[1])
	})
	var out [][2]int64
	for _, iv := range a {
		// Sharing an endpoint counts as overlapping.
		if k := len(out); k > 0 && iv[0] <= out[k-1][1] {
			out[k-1][1] = max(out[k-1][1], iv[1])
		} else {
			out = append(out, iv)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(out)) + "\n")
	for _, iv := range out {
		w.WriteString(strconv.FormatInt(iv[0], 10) + " " + strconv.FormatInt(iv[1], 10) + "\n")
	}
}
